define(['jquery'], function($) {
    'use strict';
    return function(formSelector, errorSelector, url) {
        $(formSelector).on('submit', function(event) {
            event.preventDefault();
            var zipcode = $('#zipcode').val();
            if (zipcode) {
                $.ajax({
                    url: url,
                    type: 'POST',
                    dataType: 'json',
                    data: {
                        zipcode: zipcode,
                    },
                    complete: function(response) {
                        if (response.responseJSON && response.responseJSON.error === 'zipcode_error') {
                            $(errorSelector).show();
                            return false;
                        }
                        $("#zipcode").val('');
                        $("#modal-register-complaint").modal("closeModal");
                        var windowReference = window.open();
                        windowReference.location = response.responseJSON.json_data;
                    }
                });
            }
        });
    };
});